package pw.binom.db.orm

import kotlinx.serialization.ExperimentalSerializationApi
import kotlinx.serialization.MetaSerializable
import kotlinx.serialization.SerialInfo

/**
 * Аннотации ORM.
 *
 * ## Почему `@SerialInfo`, а не свои метаданные
 *
 * ORM собирает SQL по `KSerializer`, а не по рефлексии: рефлексии в
 * Kotlin/Native нет. `@SerialInfo` — единственный способ донести
 * аннотацию до `SerialDescriptor`, откуда её читает генератор SQL.
 *
 * `@Retention(BINARY)` обязательна: `RUNTIME` в native не поддерживается.
 * `@MetaSerializable` на `@AutoGenerated` нужна, чтобы аннотация
 * переживала вложенные сериализаторы.
 */

/** Имя таблицы для класса-сущности. Без неё берётся имя класса. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.CLASS)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class TableName(val tableName: String)

/** Имя колонки для поля. Без неё берётся имя поля. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class ColumnName(val columnName: String)

/**
 * Тип колонки, общий для всех СУБД.
 *
 * Нужен, когда тип по умолчанию не подходит: например, `TEXT` вместо
 * `VARCHAR(255)` для строки. Специфичные для СУБД типы — [PgColumnType] и
 * [SqliteColumnType], они главнее.
 */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class ColumnType(val type: String)

/** Тип колонки для PostgreSQL. Главнее [ColumnType]. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class PgColumnType(val type: String)

/** Тип колонки для SQLite. Главнее [ColumnType]. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class SqliteColumnType(val type: String)

/** Первичный ключ. Пока поддерживается один ключ на сущность. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class Id

/**
 * Колонка, значение которой назначает БД.
 *
 * Исключается из `INSERT`: иначе `BIGSERIAL` получил бы явный `NULL` и
 * счётчик не сработал бы. При обновлении тоже исключается — менять
 * сгенерированный ключ нельзя.
 */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@MetaSerializable
annotation class AutoGenerated

/** Поле входит в индекс, объявленный через [Index]/[Indexes]. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class IndexColumn

/** Индекс по колонкам сущности. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.CLASS)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class Index(
    val name: String = "",
    val unique: Boolean = false,
    val columns: Array<String>,
)

/** Несколько индексов на одной сущности. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.CLASS)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class Indexes(vararg val indexes: Index)

/**
 * Вложенный объект: его поля раскладываются в колонки той же таблицы.
 *
 * Плоско, без префикса: `@Embedded val addr: Address` даёт колонки
 * `city`, `street`, а не `addr_city`. Префикс можно задать через
 * [EmbeddedPrefix], если в одной таблице два вложенных объекта с
 * одинаковыми именами полей.
 */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class Embedded

/** Префикс колонок для [Embedded]. Без него колонки плоско. */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class EmbeddedPrefix(val prefix: String)

/**
 * Экранировать имя колонки кавычками СУБД.
 *
 * Нужно для имён, совпадающих с ключевыми словами (`order`, `user`,
 * `select`). Указывать осознанно: в Postgres закавыченное имя
 * регистрозависимо, и `"Order"` ≠ `order`.
 */
@OptIn(ExperimentalSerializationApi::class)
@Target(AnnotationTarget.PROPERTY, AnnotationTarget.CLASS)
@Retention(AnnotationRetention.BINARY)
@SerialInfo
annotation class UseQuotes
